package com.example.apexphotolab.the_build.working_project.tool_panel.NES_Tile_Map_System.Vector_Sanitizer

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Paint
import android.graphics.Path
import android.graphics.Point
import com.example.apexphotolab.the_build.working_project.tool_panel.export.svg.third_shift.census.CensusReport

/**
 * Job: Vector to Bitmap Rendering Specialist.
 * Responsibility: Takes exact, closed vector paths generated by the SVG Third Shift Orchestrator
 * and paints them as solid filled shapes onto a pristine 256x240 NES Bitmap.
 * This guarantees 100% solid, razor-sharp edges without anti-aliasing fuzz.
 */
object NesVectorPainter {

    fun paintPathsToBitmap(
        width: Int,
        height: Int,
        backgroundColor: Int,
        colorGroups: Map<CensusReport, List<List<Point>>>
    ): Bitmap {
        // 1. Create a fresh, clean canvas
        val canvasBitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(canvasBitmap)

        // 2. Fill with the Universal Background Color
        canvas.drawColor(backgroundColor)

        // 3. Prepare the paint (NO anti-aliasing to guarantee sharp 1-pixel NES edges)
        val paint = Paint().apply {
            style = Paint.Style.FILL
            isAntiAlias = false
        }

        // 4. Paint every shape, grouped by its absolute truth origin color
        for ((census, paths) in colorGroups) {
            paint.color = census.dominantColor

            for (pointList in paths) {
                if (pointList.size < 3) continue // Skip invalid polygons

                val path = Path()
                path.moveTo(pointList[0].x.toFloat(), pointList[0].y.toFloat())

                for (i in 1 until pointList.size) {
                    path.lineTo(pointList[i].x.toFloat(), pointList[i].y.toFloat())
                }
                path.close() // Close the stencil loop

                canvas.drawPath(path, paint)
            }
        }

        return canvasBitmap
    }
}
